<div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Almacén</th><th>Tipo</th><th>Sexo</th><th>Talla</th><th>Cantidad</th><th>Referencia</th><th>Observaciones</th></tr></thead><tbody><?php if(!$movimientos): ?><tr><td colspan="8" class="empty">Sin movimientos.</td></tr><?php endif; foreach($movimientos as $m): ?><tr><td><?= escapar($m['fecha_movimiento']) ?></td><td><?= escapar($m['almacen']) ?></td><td><span class="status"><?= escapar($m['tipo']) ?></span></td><td><?= escapar($m['sexo']==='NINO'?'Niño':'Niña') ?></td><td><?= escapar($m['talla']) ?></td><td><?= numero($m['cantidad']) ?></td><td><?= escapar(trim(($m['referencia_tipo']??'').' '.($m['referencia_id']??''))) ?></td><td><?= escapar($m['observaciones']??'') ?></td></tr><?php endforeach; ?></tbody></table></div>
